// Reduce the incoming value to a bare hostname.
const raw = String($input.first().json.body?.domain ?? '').trim().toLowerCase();
const host = raw.replace(/^[a-z]+:\/\//, '').split('/')[0].split(':')[0].replace(/\.$/, '');
return [{ json: { host } }];

// Combine the strict HTTPS probe (is the certificate trusted?) with the
// certificate details (issuer, dates, names) into one result for Domain Guard.
// n8n hides the exact TLS failure reason, so the reason is derived from the certificate itself.
const host = $('Normalize').first().json.host;
const probe = $('TLS probe').first().json;
const details = $input.first().json;

const toMessage = (e) => (typeof e === 'string' ? e : (e?.message || JSON.stringify(e)));
const networkProblem = (m) => {
  if (/ENOTFOUND|EAI_AGAIN/.test(m)) return 'dns_failure';
  if (/ECONNREFUSED/.test(m)) return 'connection_refused';
  if (/timeout/i.test(m)) return 'timeout';
  return null;
};

const cert = details.certificate || {};
const names = (cert.alternate_names || []).map(n => n.replace(/^DNS:/, '').toLowerCase());
const covers = (name) => name === host || (name.startsWith('*.') && host.endsWith(name.slice(1)) && host.split('.').length === name.split('.').length);
const hostname_match = names.length ? names.some(covers) : null;
const now = new Date();
const validFrom = cert.valid_from ? new Date(cert.valid_from) : null;
const validTo = cert.valid_to ? new Date(cert.valid_to) : null;

const probeError = probe.error ? toMessage(probe.error) : null;
let problem = null;
if (probeError) {
  problem = networkProblem(probeError);
  if (!problem) {
    if (validTo && now > validTo) problem = 'expired';
    else if (validFrom && now < validFrom) problem = 'not_yet_valid';
    else if (hostname_match === false) problem = 'hostname_mismatch';
    else if (cert.issued_by && cert.issued_by === cert.issued_to) problem = 'self_signed';
    else if (cert.issued_by) problem = 'untrusted_chain';
    else problem = 'tls_error';
  }
}

return [{ json: {
  domain: host,
  valid: !probeError,
  problem,
  error: probeError,
  days_until_expiry: validTo ? Math.floor((validTo - now) / 86400000) : null,
  valid_from: cert.valid_from ?? null,
  valid_to: cert.valid_to ?? null,
  issued_to: cert.issued_to ?? null,
  issuer: cert.issued_by ?? null,
  hostname_match,
  names,
  details_source: 'networkcalc.com',
} }];
